"""Homepage case panel styling; decorative icons do not change text."""

CSS = '\n#home-case{position:relative;isolation:isolate;overflow:hidden;border:0;border-radius:15px;padding:37px 36px 30px;background:radial-gradient(ellipse at 100% 0,#d6e7dc90,transparent 58%),linear-gradient(120deg,#edf3e9,#f6f7ef 75%);box-shadow:inset 0 1px 0 #ffffffc0,0 12px 35px -30px #385b3d45}\n#home-case::after{content:\'\';position:absolute;z-index:-1;pointer-events:none;width:220px;height:220px;border:1px solid #b5cbbb50;border-radius:50%;right:-75px;top:-110px;box-shadow:0 0 0 22px #c4d8c52b,0 0 0 50px #c4d8c51c}\n#home-case .section-kicker{color:#708d72;font-size:10px;letter-spacing:.2em;display:flex;align-items:center;gap:9px;margin-bottom:13px}\n#home-case .section-kicker::before{content:\'\';width:6px;height:6px;background:#7f9f79;border-radius:2px;box-shadow:0 0 0 4px #dbe7d5}\n#home-case h2{color:#294e3a;font-size:29px;line-height:1.5;letter-spacing:-.025em;margin-bottom:20px}\n#home-case>p{font-size:13px;color:#637965;line-height:2;max-width:860px}\n#home-case .case-tags{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:24px 0}\n#home-case .case-tags>span{display:flex;gap:12px;align-items:center;min-width:0;padding:16px 14px;border:0;border-radius:9px;background:#ffffffad;box-shadow:0 3px 10px #3e624505,inset 0 1px 0 #fff;font-size:11px;color:#486951;line-height:1.7}\n#home-case .case-tags>span::before{content:\'\';width:33px;height:33px;flex:0 0 33px;border-radius:9px;background-color:#deead9;background-position:center;background-repeat:no-repeat;background-size:21px}\n#home-case .case-tags>span:nth-child(2){color:#496e7c}\n#home-case .case-tags>span:nth-child(2)::before{background-color:#e0ebee}\n#home-case .case-tags>span:nth-child(3){color:#7c684b}\n#home-case .case-tags>span:nth-child(3)::before{background-color:#eee6d7}\n#home-case .reading-guide{font-size:11px;line-height:1.95;color:#81907c;margin-bottom:0}\n@media(max-width:760px){#home-case{padding:28px 23px 24px;border-radius:12px}#home-case h2{font-size:25px;margin-bottom:17px}#home-case>p{font-size:12px;line-height:2}#home-case .case-tags{grid-template-columns:1fr;gap:9px;margin:21px 0}#home-case .case-tags>span{padding:12px 13px;font-size:12px}#home-case .reading-guide{font-size:11px}}\n#home-case .case-tags>span:nth-child(1)::before{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23537c57%22%20stroke-width%3D%221.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M6%205h12a3%203%200%200%201%203%203v7a3%203%200%200%201-3%203h-7l-5%203v-3a3%203%200%200%201-3-3V8a3%203%200%200%201%203-3Z%22%2F%3E%3Cpath%20d%3D%22M8%2010h8M8%2014h5%22%2F%3E%3C%2Fsvg%3E")}\n#home-case .case-tags>span:nth-child(2)::before{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%23547b8a%22%20stroke-width%3D%221.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Cpath%20d%3D%22M14%203H7a2%202%200%200%200-2%202v14a2%202%200%200%200%202%202h10a2%202%200%200%200%202-2V8Z%22%2F%3E%3Cpath%20d%3D%22M14%203v5h5M9%2012h6M9%2016h6%22%2F%3E%3C%2Fsvg%3E")}\n#home-case .case-tags>span:nth-child(3)::before{background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2024%2024%22%20fill%3D%22none%22%20stroke%3D%22%2396784d%22%20stroke-width%3D%221.4%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%3E%3Crect%20x%3D%224%22%20y%3D%227%22%20width%3D%2216%22%20height%3D%2213%22%20rx%3D%224%22%2F%3E%3Cpath%20d%3D%22M12%203v4M2%2012v4M22%2012v4M9%2016h6%22%2F%3E%3Ccircle%20cx%3D%229%22%20cy%3D%2212%22%20r%3D%22.7%22%2F%3E%3Ccircle%20cx%3D%2215%22%20cy%3D%2212%22%20r%3D%22.7%22%2F%3E%3C%2Fsvg%3E")}\n'
